// -------------------------------------------------------------
// COVENANT ENGINE & SETTINGS
// -------------------------------------------------------------
let currentSettings: any = {
    always_on_top: false,
    privacy_enabled: false,
    privacy_blur_photos: false,
    privacy_blur_names: false,
    privacy_blur_messages: false,
    privacy_blur_on_window_blur: false,
    theme: "default"
};

function getOrCreateStyle(id: string): HTMLStyleElement {
    let style = document.getElementById(id) as HTMLStyleElement;
    if (!style) {
        style = document.createElement("style");
        style.id = id;
        document.head.appendChild(style);
    }
    return style;
}

// 1. Live Theme Application
function applyTheme(themeName: string) {
    const style = getOrCreateStyle("covenant-theme-style");
    if (!themeName || themeName === "default") {
        style.textContent = "";
        document.body.classList.remove("covenant-themed");
        document.documentElement.removeAttribute("data-theme");
        const nativeTheme = localStorage.getItem("theme");
        if (nativeTheme !== "dark") {
            document.body.classList.remove("dark");
        }
        return;
    }

    const css = getThemeCss(themeName);
    style.textContent = css || "";
    document.body.classList.add("dark");
    document.body.classList.remove("light");
    document.documentElement.setAttribute("data-theme", "dark");
    document.body.classList.add("covenant-themed");
}

// 2. Anti-Spy Privacy
function applyPrivacy(settings: any) {
    const style = getOrCreateStyle("covenant-privacy-style");
    if (!settings.privacy_enabled) {
        style.textContent = "";
        return;
    }

    let css = "";

    if (settings.privacy_blur_photos) {
        css += `
            /* Blur Avatars */
            img[src*="user"], img[src*="dyn"], div[data-testid="avatar-container"], img[alt*="avatar"] {
                filter: blur(10px) !important;
                transition: filter 0.2s ease !important;
            }
            img[src*="user"]:hover, img[src*="dyn"]:hover, div[data-testid="avatar-container"]:hover, img[alt*="avatar"]:hover {
                filter: blur(0px) !important;
            }
        `;
    }

    if (settings.privacy_blur_names) {
        css += `
            /* Blur Contact Names */
            div[data-testid="cell-frame-title"], header span[dir="auto"], span[title] {
                filter: blur(6px) !important;
                transition: filter 0.2s ease !important;
            }
            div[data-testid="cell-frame-title"]:hover, header span[dir="auto"]:hover, span[title]:hover {
                filter: blur(0px) !important;
            }
        `;
    }

    if (settings.privacy_blur_messages) {
        css += `
            /* Blur Message Previews and Chat Bubbles */
            div[data-testid="cell-frame-secondary"], div[data-testid="msg-container"] span[dir="auto"] {
                filter: blur(7px) !important;
                transition: filter 0.2s ease !important;
            }
            div[data-testid="cell-frame-secondary"]:hover, div[data-testid="msg-container"] span[dir="auto"]:hover {
                filter: blur(0px) !important;
            }
        `;
    }

    if (settings.privacy_blur_on_window_blur) {
        css += `
            body.covenant-window-blurred #app {
                filter: blur(14px) !important;
                transition: filter 0.25s ease !important;
            }
        `;
    }

    style.textContent = css;
}

// 3. In-Dock Covenant Gear Button (Directly above native Settings)
function injectCovenantDockButton() {
    if (document.getElementById("covenant-dock-btn")) return;

    // Look for WhatsApp settings button in the left dock
    const settingsBtn = document.querySelector<HTMLElement>(
        'button[aria-label*="Configuraç"], button[aria-label*="Setting"], ' +
        'div[role="button"][aria-label*="Configuraç"], div[role="button"][aria-label*="Setting"], ' +
        'span[data-icon="settings"], span[data-icon="settings-refreshed"], span[data-icon="settings-outline"]'
    );
    if (!settingsBtn) return;

    const actualBtn = (settingsBtn.closest('button, div[role="button"]') as HTMLElement) || settingsBtn;

    // Ascend to the item wrapper inside the dock container
    let itemWrapper: HTMLElement = actualBtn;
    while (itemWrapper.parentElement && itemWrapper.parentElement.tagName === 'DIV' && itemWrapper.parentElement.children.length === 1) {
        itemWrapper = itemWrapper.parentElement;
    }
    const container = itemWrapper.parentElement;
    if (!container) return;

    const covItem = document.createElement("div");
    covItem.id = "covenant-dock-item";
    covItem.style.cssText = "display: flex; justify-content: center; align-items: center; margin: 4px 0;";

    const btn = document.createElement("button");
    btn.id = "covenant-dock-btn";
    btn.type = "button";
    btn.title = "Configurações Covenant (Ctrl+,)";
    btn.setAttribute("aria-label", "Configurações Covenant");
    btn.style.cssText = `
        width: 44px;
        height: 44px;
        border-radius: 50%;
        border: none;
        background: transparent;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 6px;
        transition: background 0.2s, transform 0.2s;
        box-sizing: border-box;
    `;

    btn.innerHTML = `
        <img src="data:image/png;base64," 
             style="width: 28px; height: 28px; object-fit: contain; pointer-events: none; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3));"
             alt="Covenant">
    `;

    btn.addEventListener("mouseenter", () => {
        btn.style.background = "rgba(0, 168, 132, 0.25)";
        btn.style.transform = "scale(1.1)";
    });
    btn.addEventListener("mouseleave", () => {
        if (!isDrawerOpen) {
            btn.style.background = "transparent";
            btn.style.transform = "scale(1)";
        }
    });
    btn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        toggleCovenantDrawer();
    });

    covItem.appendChild(btn);
    // Inserts directly above the WhatsApp Settings button in the left dock
    container.insertBefore(covItem, itemWrapper);
}

